module uart_tx(clk, rst, tx_start, tx_data, tx_serial, tx_busy, tx_done);
  input clk;
  input rst;
  input tx_start;
  input [7:0] tx_data;
  output reg tx_serial;
  output reg tx_busy;
  output reg tx_done;

  reg [2:0] state;
  reg [7:0] clk_count;
  reg [2:0] bit_index;
  reg [7:0] tx_shift;

  localparam [2:0] ST_IDLE  = 3'b000;
  localparam [2:0] ST_START = 3'b001;
  localparam [2:0] ST_DATA  = 3'b010;
  localparam [2:0] ST_STOP  = 3'b011;
  localparam [2:0] ST_DONE  = 3'b100;

  wire baud_tick;

  assign baud_tick = clk_count[7] |
                     (clk_count[6] &
                       (clk_count[5] |
                         (clk_count[4] &
                           (clk_count[3] | (clk_count[2] & clk_count[1])))));

  always @(posedge clk) begin
    if (rst) begin
      state     <= ST_IDLE;
      clk_count <= 8'd0;
      bit_index <= 3'd0;
      tx_busy   <= 1'b0;
      tx_done   <= 1'b0;
      tx_serial <= 1'b1;
    end else begin
      tx_done <= (state == ST_STOP) && baud_tick;

      case (state)
        ST_IDLE: begin
          state     <= tx_start ? ST_START : ST_IDLE;
          clk_count <= 8'd0;
          bit_index <= 3'd0;
        end

        ST_START: begin
          if (baud_tick) begin
            state     <= ST_DATA;
            clk_count <= 8'd0;
          end else begin
            state     <= ST_START;
            clk_count <= clk_count + 8'd1;
          end
        end

        ST_DATA: begin
          if (baud_tick) begin
            clk_count <= 8'd0;
            if (bit_index == 3'd7) begin
              state     <= ST_STOP;
              bit_index <= 3'd0;
            end else begin
              state     <= ST_DATA;
              bit_index <= bit_index + 3'd1;
            end
          end else begin
            state     <= ST_DATA;
            clk_count <= clk_count + 8'd1;
          end
        end

        ST_STOP: begin
          if (baud_tick) begin
            state     <= ST_DONE;
            clk_count <= 8'd0;
          end else begin
            state     <= ST_STOP;
            clk_count <= clk_count + 8'd1;
          end
        end

        ST_DONE: begin
          state     <= ST_IDLE;
          clk_count <= clk_count;
        end

        default: begin
          state     <= ST_IDLE;
          clk_count <= 8'd0;
          bit_index <= 3'd0;
        end
      endcase

      if ((state == ST_IDLE) && tx_start)
        tx_shift <= tx_data;

      if ((state == ST_IDLE) && tx_start)
        tx_busy <= 1'b1;
      else if ((state == ST_STOP) && baud_tick)
        tx_busy <= 1'b0;
      else if (state == ST_IDLE)
        tx_busy <= 1'b0;
      else
        tx_busy <= tx_busy;

      case (state)
        ST_IDLE:  tx_serial <= 1'b1;
        ST_START: tx_serial <= 1'b0;
        ST_DATA:  tx_serial <= tx_shift[bit_index];
        ST_STOP:  tx_serial <= 1'b1;
        ST_DONE:  tx_serial <= tx_serial;
        default:  tx_serial <= 1'b1;
      endcase
    end
  end

endmodule

